Extensions.ExtractScript:
param(
    [xml] $Document
);

foreach( $file in $Document.unattend.Extensions.File ) {
    $path = [System.Environment]::ExpandEnvironmentVariables( $file.GetAttribute( 'path' ) );
    mkdir -Path( $path | Split-Path -Parent ) -ErrorAction 'SilentlyContinue';
    $encoding = switch( [System.IO.Path]::GetExtension( $path ) ) {
        { $_ -in '.ps1', '.xml' } { [System.Text.Encoding]::UTF8; }
        default { [System.Text.Encoding]::Default; }
    };
    $bytes = $encoding.GetPreamble() + $encoding.GetBytes( $file.InnerText.Trim() );
    [System.IO.File]::WriteAllBytes( $path, $bytes );
}

Extensions.File:
$scripts = @(
	{
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\OOBE" /v BypassNRO /t REG_DWORD /d 1 /f;
	};
	{
		net.exe accounts /maxpwage:UNLIMITED;
	};
	{
		# Block automatic device encryption (BitLocker). "Finish Setup" on the desktop asks whether to allow it again.
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Control\BitLocker" /v PreventDeviceEncryption /t REG_DWORD /d 1 /f;
	};
	{
		netsh.exe wlan add profile filename="C:\Windows\Setup\Scripts\OEMWifi.xml" user=all;
		Remove-Item -LiteralPath 'C:\Windows\Setup\Scripts\OEMWifi.xml' -Force -ErrorAction 'SilentlyContinue';
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to customize your Windows installation. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\OEMSpecialize.log";

$mutex = New-Object System.Threading.Mutex($false, 'Global\OEMUpdate')
if (-not $mutex.WaitOne(0)) { exit }   # already running

$ErrorActionPreference = 'Continue'
$ProgressPreference    = 'SilentlyContinue'
$logFile     = 'C:\Windows\Setup\Scripts\OEMUpdate.log'
$stateFile   = 'C:\Windows\Setup\Scripts\OEMUpdatePass.txt'
$confirmFile = 'C:\Windows\Setup\Scripts\OEMUpdateConfirm.txt'   # exists = already restarted once after an empty search
$launcher    = 'C:\ProgramData\Microsoft\Windows\Start Menu\Programs\StartUp\OEMUpdate.cmd'
$maxPasses   = 10

# ---------- console look ----------
$raw = $Host.UI.RawUI
try { $raw.WindowTitle = 'Windows Update - do not close' } catch { }
try {
    $raw.BackgroundColor = 'Black'; $raw.ForegroundColor = 'Gray'
    $buf = $raw.BufferSize; if ($buf.Width -lt 100) { $buf.Width = 100; $raw.BufferSize = $buf }
    $win = $raw.WindowSize; $win.Width = 100; $win.Height = 34; $raw.WindowSize = $win
} catch { }
Clear-Host

function Log([string] $m) {
    try { Add-Content -Path $logFile -Value ('{0:dd.MM.yyyy HH.mm.ss}  {1}' -f (Get-Date), $m) } catch { }
}


# ---------- screen helpers ----------
$script:sub   = ''
$script:items = @()   # each: @{ Mark = '  '; Title = '...' }
$script:steps = @()   # finished steps of this pass: @{ Name = 'Search'; Time = [TimeSpan] }
$script:startTime = $null

function Short([string] $t, [int] $n = 78) { if ($t.Length -gt $n) { $t.Substring(0, $n - 3) + '...' } else { $t } }
function Fmt([TimeSpan] $ts) { '{0:00}:{1:00}:{2:00}' -f [int][math]::Floor($ts.TotalHours), $ts.Minutes, $ts.Seconds }
function TotalTime { if ($script:startTime) { Fmt ((Get-Date) - $script:startTime) } else { '--:--:--' } }

function Draw([string[]] $lines, [string] $color = 'Gray') {
    Clear-Host
    Write-Host ''
    Write-Host '   ============================================' -ForegroundColor DarkGray
    Write-Host "     WINDOWS UPDATE  -  $script:sub" -ForegroundColor Gray
    Write-Host '   ============================================' -ForegroundColor DarkGray
    Write-Host "   Total time since first start: $(TotalTime)" -ForegroundColor DarkGray
    Write-Host ''
    if ($script:items.Count -gt 0) {
        Write-Host "   Updates ($($script:items.Count)):"
        foreach ($i in $script:items) {
            $c = switch ($i.Mark) { 'OK' { 'Gray' } '!!' { 'Yellow' } '>>' { 'Yellow' } default { 'DarkGray' } }
            Write-Host ('    [{0,-2}]  ' -f $i.Mark) -ForegroundColor $c -NoNewline
            Write-Host (Short $i.Title)
        }
        Write-Host ''
    }
    if ($script:steps.Count -gt 0) {
        Write-Host '   Steps this pass:'
        foreach ($s in $script:steps) {
            Write-Host ('    {0,-12}' -f $s.Name) -NoNewline
            Write-Host (Fmt $s.Time) -ForegroundColor Gray
        }
        Write-Host ''
    }
    foreach ($l in $lines) { Write-Host "   $l" -ForegroundColor $color }
}

function Footer {
    Write-Host ''
    Write-Host '   Do not close this window. The PC restarts automatically when needed.' -ForegroundColor DarkGray
}

# Ticking timer on one line while the main thread is busy in a blocking Windows Update call.
function Start-Ticker([string] $label) {
    Write-Host ''
    Footer
    $row = [Console]::CursorTop - 3
    $ps = [PowerShell]::Create()
    [void] $ps.AddScript({
        param($row, $label)
        $sw = [Diagnostics.Stopwatch]::StartNew()
        while ($true) {
            try {
                [Console]::SetCursorPosition(3, $row)
                [Console]::ForegroundColor = 'Yellow'
                [Console]::Write(('{0,-44}{1:hh\:mm\:ss}' -f $label, $sw.Elapsed))
                [Console]::ForegroundColor = 'Gray'
            } catch { }
            Start-Sleep -Milliseconds 1000
        }
    }).AddArgument($row).AddArgument($label)
    return @{ PS = $ps; Handle = $ps.BeginInvoke(); SW = [Diagnostics.Stopwatch]::StartNew() }
}
function Stop-Ticker($t, [string] $name) {
    try { $t.PS.Stop(); $t.PS.Dispose() } catch { }
    $el = $t.SW.Elapsed
    $script:steps += @{ Name = $name; Time = $el }
    return $el
}

function Restart-WithCountdown([string] $why) {
    Log "Restart: $why"
    for ($s = 10; $s -gt 0; $s--) {
        Draw @($why, '', "Restarting in $s s...") 'Yellow'
        Start-Sleep -Seconds 1
    }
    Restart-Computer -Force
    exit
}

# Windows' own updater can still install drivers in the background after a restart
# (for example audio add-on drivers). Give it time, trigger its scan and wait until it is idle.
function Invoke-FinalCheck {
    $script:steps = @()
    Draw @('Final check: letting Windows finish background installs (a few minutes).')
    $t = Start-Ticker 'Final check...'
    $up = (Get-Date) - (Get-CimInstance Win32_OperatingSystem).LastBootUpTime
    if ($up.TotalSeconds -lt 180) { Start-Sleep -Seconds ([int](180 - $up.TotalSeconds)) }
    try { Start-Process -FilePath "$env:WINDIR\System32\UsoClient.exe" -ArgumentList 'StartScan' -WindowStyle Hidden } catch { }
    $quiet = 0; $sawBusy = $false
    for ($s = 0; $s -lt 360; $s += 10) {
        Start-Sleep -Seconds 10
        $busy = $false; try { $busy = (New-Object -ComObject Microsoft.Update.Installer).IsBusy } catch { }
        $rb = $false; try { $rb = (New-Object -ComObject Microsoft.Update.SystemInfo).RebootRequired } catch { }
        if ($rb) { break }
        if ($busy) { $quiet = 0; $sawBusy = $true } else { $quiet += 10 }
        if ($s -ge 120 -and $quiet -ge 90) { break }
    }
    $el = Stop-Ticker $t 'Final check'
    Log ('Final check took {0:mm\:ss}, Windows busy in background: {1}' -f $el, $sawBusy)
}

function Show-Done([string] $msg, [int] $icon = 64) {
    Remove-Item -LiteralPath $launcher -Force -ErrorAction SilentlyContinue
    $lines = @($msg, '')
    $bad = @(Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue | Where-Object { $_.ConfigManagerErrorCode -ne 0 })
    if ($bad.Count -gt 0) {
        $icon = 48
        $lines += "Devices with driver problems ($($bad.Count)):"
        foreach ($d in ($bad | Select-Object -First 10)) {
            $n = if ($d.Name) { $d.Name } else { $d.DeviceID }
            $lines += "  - $(Short $n 70) (code $($d.ConfigManagerErrorCode))"
        }
        if ($bad.Count -gt 10) { $lines += "  ...and $($bad.Count - 10) more" }
        $lines += 'Check Device Manager and the manufacturer''s support site.'
    } else {
        $lines += 'Devices: all OK'
    }
    $lines += ''
    $lines += "Total update time: $(TotalTime)"
    Remove-Item -LiteralPath $startFile -Force -ErrorAction SilentlyContinue
    $script:sub = 'Finished'
    Draw $lines $(if ($icon -eq 48) { 'Yellow' } else { 'Gray' })
    Write-Host ''
    Write-Host '   Next: run "Finish Setup" on the desktop when ready.' -ForegroundColor DarkGray
    $lines | ForEach-Object { Log $_ }
    (New-Object -ComObject WScript.Shell).Popup(($lines -join "`n"), 0, 'Windows Update', $icon) | Out-Null
    exit
}

# ---------- pass bookkeeping ----------
$startFile = 'C:\Windows\Setup\Scripts\OEMUpdateStart.txt'
if (-not (Test-Path $startFile)) { Set-Content -Path $startFile -Value (Get-Date).ToString('o') }
try { $script:startTime = [datetime]::Parse((Get-Content $startFile -TotalCount 1), $null, 'RoundtripKind') } catch { $script:startTime = Get-Date }
$pass = 1
if (Test-Path $stateFile) { $pass = [int](Get-Content $stateFile) + 1 }
Set-Content -Path $stateFile -Value $pass
$script:sub = "Pass $pass"
Log "=== Pass $pass ==="
if ($pass -gt $maxPasses) { Show-Done "Stopped after $maxPasses passes. Check Windows Update manually." 48 }

# ---------- wait for internet (max 5 min) ----------
Draw @('Waiting for internet connection...')
netsh.exe wlan connect name=Tietoleppa | Out-Null
$online = $false
for ($i = 0; $i -lt 60; $i++) {
    try {
        Invoke-WebRequest -Uri 'http://www.msftconnecttest.com/connecttest.txt' -UseBasicParsing -TimeoutSec 5 | Out-Null
        $online = $true; break
    } catch { Start-Sleep -Seconds 5 }
}
if (-not $online) {
    Set-Content -Path $stateFile -Value ($pass - 1)   # launcher stays, retries on next logon
    Log 'No internet.'
    Draw @('No internet connection.', '', 'Connect a network cable or Wi-Fi, then sign out and in or restart to retry.') 'Yellow'
    (New-Object -ComObject WScript.Shell).Popup('No internet. Connect network and sign out/in or restart to retry.', 0, 'Windows Update', 48) | Out-Null
    exit
}

# ---------- update loop ----------
$script:finalDone = $false
$session  = New-Object -ComObject Microsoft.Update.Session
$searcher = $session.CreateUpdateSearcher()
$searcher.ServerSelection = 2   # Windows Update online (same source as Settings), includes drivers
$searcher.Online = $true

while ($true) {
    $script:items = @()
    $script:steps = @()
    Draw @('Searching for updates. The first search on a fresh install can take 10-20 min.')
    $t = Start-Ticker 'Searching...'
    $result = $searcher.Search('IsInstalled=0 and IsHidden=0')
    $el = Stop-Ticker $t 'Search'
    Log ('Search took {0:mm\:ss}, found {1}' -f $el, $result.Updates.Count)

    $todo = New-Object -ComObject Microsoft.Update.UpdateColl
    foreach ($u in $result.Updates) {
        if ($u.InstallationBehavior.CanRequestUserInput) { continue }
        if (-not $u.EulaAccepted) { $u.AcceptEula() }
        [void] $todo.Add($u)
        $script:items += @{ Mark = '  '; Title = $u.Title }
        Log "  found: $($u.Title)"
    }

    if ($todo.Count -eq 0) {
        $rebootPending = $false
        try { $rebootPending = (New-Object -ComObject Microsoft.Update.SystemInfo).RebootRequired } catch { }
        if ($rebootPending) {
            Remove-Item -LiteralPath $confirmFile -Force -ErrorAction SilentlyContinue
            Restart-WithCountdown 'No new updates, but a restart is pending. Checking again after it.'
        }
        if (-not (Test-Path $confirmFile)) {
            Set-Content -Path $confirmFile -Value 'confirm'
            Restart-WithCountdown 'No updates found. Restarting once to catch follow-up updates (drivers often appear after a restart).'
        }
        if (-not $script:finalDone) {
            Invoke-FinalCheck
            $script:finalDone = $true
            $rb = $false; try { $rb = (New-Object -ComObject Microsoft.Update.SystemInfo).RebootRequired } catch { }
            if ($rb) { Restart-WithCountdown 'Windows installed an update in the background that needs a restart. Checking again after it.' }
            continue   # search once more
        }
        Remove-Item -LiteralPath $confirmFile -Force -ErrorAction SilentlyContinue
        Show-Done 'All updates installed (confirmed after a restart and a final check).'
    }
    Remove-Item -LiteralPath $confirmFile -Force -ErrorAction SilentlyContinue

    # download
    foreach ($i in $script:items) { $i.Mark = '>>' }
    Draw @()
    $t = Start-Ticker "Downloading $($todo.Count) update(s)..."
    $dl = $session.CreateUpdateDownloader(); $dl.Updates = $todo
    try { [void] $dl.Download() } catch { Log "Download error: $($_.Exception.Message)" }
    $el = Stop-Ticker $t 'Download'
    Log ('Download took {0:mm\:ss}' -f $el)

    # install
    Draw @()
    $t = Start-Ticker "Installing $($todo.Count) update(s)..."
    $inst = $session.CreateUpdateInstaller(); $inst.Updates = $todo
    $r = $null
    try { $r = $inst.Install() } catch { Log "Install error: $($_.Exception.Message)" }
    $el = Stop-Ticker $t 'Install'
    Log ('Install took {0:mm\:ss}' -f $el)

    $reboot = $false
    for ($k = 0; $k -lt $todo.Count; $k++) {
        $code = if ($r) { [int] $r.GetUpdateResult($k).ResultCode } else { 4 }
        $script:items[$k].Mark = if ($code -in 2, 3) { 'OK' } else { '!!' }
        Log ("  [{0}] {1}" -f $script:items[$k].Mark, $todo.Item($k).Title)
    }
    if ($r) { $reboot = $r.RebootRequired }

    if ($reboot) { Restart-WithCountdown 'Updates installed. A restart is required to finish them.' }

    $pass++
    Set-Content -Path $stateFile -Value $pass
    $script:sub = "Pass $pass"
    Log "=== Pass $pass ==="
    if ($pass -gt $maxPasses) { Show-Done "Stopped after $maxPasses passes. Check Windows Update manually." 48 }
}

# Started hidden (conhost --headless) from the Startup folder at every audit mode logon.
# Audit mode opens the Sysprep window at every logon; close it until "Finish Setup" runs.
# "Finish Setup" creates the flag file before starting Sysprep itself, so its run is never closed.
$flag = 'C:\Windows\Setup\Scripts\OEMFinishing.flag'
for ($i = 0; $i -lt 120; $i++) {
    if (Test-Path $flag) { break }
    Get-Process -Name sysprep -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
    Start-Sleep -Seconds 1
}

# Called by "Finish Setup.cmd". Exit code 1 = something needs attention.
$problems = 0

$names = @{ 0 = 'Unlicensed'; 1 = 'Activated'; 2 = 'Initial grace period'; 3 = 'Additional grace period'; 4 = 'Non-genuine grace period'; 5 = 'Notification mode'; 6 = 'Extended grace period' }
$lic = Get-CimInstance SoftwareLicensingProduct -Filter "ApplicationID='55c92734-d682-4d71-983e-d6ec3f16059f' AND PartialProductKey IS NOT NULL" -ErrorAction SilentlyContinue | Select-Object -First 1
$edition = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue).EditionID
Write-Host ''
Write-Host "   Edition    : $edition"
if ($lic) {
    $state = $names[[int]$lic.LicenseStatus]
    if ($lic.LicenseStatus -eq 1) {
        Write-Host "   Activation : $state" -ForegroundColor Gray
    } else {
        Write-Host "   Activation : $state" -ForegroundColor Yellow
        Write-Host '                Check that the installed edition matches the PC''s license (Home vs Pro).' -ForegroundColor Yellow
        $problems++
    }
} else {
    Write-Host '   Activation : no product key found' -ForegroundColor Yellow
    $problems++
}

$bad = @(Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue | Where-Object { $_.ConfigManagerErrorCode -ne 0 })
if ($bad.Count -gt 0) {
    Write-Host "   Devices    : $($bad.Count) with driver problems" -ForegroundColor Yellow
    foreach ($d in $bad) {
        $n = if ($d.Name) { $d.Name } else { $d.DeviceID }
        Write-Host "                - $n (code $($d.ConfigManagerErrorCode))" -ForegroundColor Yellow
    }
    $problems++
} else {
    Write-Host '   Devices    : all OK' -ForegroundColor Gray
}

exit [int]($problems -gt 0)
